PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS campus (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, code TEXT NOT NULL UNIQUE, display_name TEXT, logo_path TEXT, qr_path TEXT, remarks TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('super_admin','manager','teacher')), campus_id INTEGER REFERENCES campus(id), is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS course (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), name TEXT NOT NULL, category TEXT DEFAULT '其他', is_archived INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS class_group (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), course_id INTEGER NOT NULL REFERENCES course(id), name TEXT NOT NULL, teacher_id INTEGER REFERENCES user(id), weekday TEXT NOT NULL DEFAULT '周六', start_time TEXT NOT NULL DEFAULT '09:00', end_time TEXT NOT NULL DEFAULT '10:30', room TEXT DEFAULT '', capacity INTEGER DEFAULT 0, deduct_lessons INTEGER DEFAULT 1 CHECK(deduct_lessons BETWEEN 1 AND 8), allow_override INTEGER DEFAULT 0, override_extra INTEGER DEFAULT 0, is_archived INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), name TEXT NOT NULL, gender TEXT DEFAULT '', parent_name TEXT DEFAULT '', phone TEXT DEFAULT '', birthday TEXT, grade TEXT DEFAULT '', remarks TEXT DEFAULT '', status TEXT DEFAULT 'active' CHECK(status IN ('active','trial','archived')), source TEXT DEFAULT 'manual', registration_id INTEGER, lessons_remaining INTEGER NOT NULL DEFAULT 0 CHECK(lessons_remaining>=0), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enrollment (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), student_id INTEGER NOT NULL REFERENCES student(id), class_group_id INTEGER NOT NULL REFERENCES class_group(id), status TEXT DEFAULT 'active' CHECK(status IN ('active','left')), joined_at TEXT DEFAULT CURRENT_TIMESTAMP, left_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(student_id,class_group_id));
CREATE TABLE IF NOT EXISTS payment_record (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), student_id INTEGER NOT NULL REFERENCES student(id), contract_id INTEGER, type TEXT NOT NULL CHECK(type IN ('charge','adjust')), amount_cents INTEGER DEFAULT 0, lessons_delta INTEGER NOT NULL DEFAULT 0, lessons_bonus INTEGER DEFAULT 0, operator_id INTEGER REFERENCES user(id), remarks TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campus_expense (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), category TEXT NOT NULL, amount_cents INTEGER NOT NULL, remarks TEXT DEFAULT '', operator_id INTEGER REFERENCES user(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lesson_record (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), class_group_id INTEGER NOT NULL REFERENCES class_group(id), student_id INTEGER NOT NULL REFERENCES student(id), contract_id INTEGER, teacher_id INTEGER NOT NULL REFERENCES user(id), date TEXT DEFAULT CURRENT_TIMESTAMP, duration_minutes INTEGER DEFAULT 60, status TEXT DEFAULT 'present', deducted_lessons INTEGER DEFAULT 1, revoked_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registration_entry (id INTEGER PRIMARY KEY, campus_id INTEGER NOT NULL REFERENCES campus(id), name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, enabled INTEGER DEFAULT 1, deadline TEXT, contact TEXT DEFAULT '', qr_path TEXT, created_by INTEGER REFERENCES user(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registration (id INTEGER PRIMARY KEY, entry_id INTEGER NOT NULL REFERENCES registration_entry(id), campus_id INTEGER NOT NULL REFERENCES campus(id), class_group_id INTEGER NOT NULL REFERENCES class_group(id), student_name TEXT NOT NULL, grade TEXT DEFAULT '', guardian_name TEXT DEFAULT '', guardian_phone TEXT DEFAULT '', phone_last4 TEXT DEFAULT '', status TEXT DEFAULT 'pending', modify_code_hash TEXT, modify_uses INTEGER DEFAULT 0, note TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(entry_id,student_name,grade,phone_last4));
CREATE TABLE IF NOT EXISTS registration_history (id INTEGER PRIMARY KEY, registration_id INTEGER NOT NULL REFERENCES registration(id), action TEXT NOT NULL, from_class_group_id INTEGER, to_class_group_id INTEGER, note TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS operation_log (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES user(id), action_time TEXT DEFAULT CURRENT_TIMESTAMP, target TEXT, target_id INTEGER, action TEXT, detail TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS system_config (id INTEGER PRIMARY KEY, site_name TEXT DEFAULT '课时本', logo_path TEXT, login_bg_path TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quick_deduct (id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES student(id), class_group_id INTEGER NOT NULL REFERENCES class_group(id), local_day TEXT NOT NULL, lesson_record_id INTEGER REFERENCES lesson_record(id), operator_id INTEGER NOT NULL REFERENCES user(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(student_id,class_group_id,local_day));
CREATE TABLE IF NOT EXISTS lesson_batch (nonce TEXT PRIMARY KEY, class_group_id INTEGER REFERENCES class_group(id), operator_id INTEGER NOT NULL REFERENCES user(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_share (id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL UNIQUE REFERENCES student(id), token TEXT NOT NULL UNIQUE, enabled INTEGER DEFAULT 0, public_name TEXT DEFAULT '', approved_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS artwork (id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES student(id), campus_id INTEGER NOT NULL REFERENCES campus(id), uploader_id INTEGER NOT NULL REFERENCES user(id), image_key TEXT NOT NULL UNIQUE, title TEXT DEFAULT '课堂作品', note TEXT DEFAULT '', is_public INTEGER DEFAULT 0, is_deleted INTEGER DEFAULT 0, likes_count INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS artwork_like (artwork_id INTEGER NOT NULL REFERENCES artwork(id), ip_hash TEXT NOT NULL, last_at INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(artwork_id,ip_hash));
CREATE TRIGGER IF NOT EXISTS artwork_like_insert AFTER INSERT ON artwork_like BEGIN UPDATE artwork SET likes_count=likes_count+1 WHERE id=NEW.artwork_id; END;
CREATE TRIGGER IF NOT EXISTS artwork_like_update AFTER UPDATE OF last_at ON artwork_like WHEN NEW.last_at>OLD.last_at BEGIN UPDATE artwork SET likes_count=likes_count+1 WHERE id=NEW.artwork_id; END;
CREATE TABLE IF NOT EXISTS session (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES user(id), csrf_token TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempt (ip_hash TEXT NOT NULL, bucket INTEGER NOT NULL, fails INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'login', PRIMARY KEY(ip_hash,bucket));
CREATE INDEX IF NOT EXISTS idx_enroll_class ON enrollment(class_group_id,status);
CREATE INDEX IF NOT EXISTS idx_enroll_student ON enrollment(student_id,status);
CREATE INDEX IF NOT EXISTS idx_lessons_student ON lesson_record(student_id,date);
CREATE INDEX IF NOT EXISTS idx_lessons_class ON lesson_record(class_group_id,date);
CREATE INDEX IF NOT EXISTS idx_artwork_student ON artwork(student_id,is_deleted,created_at);
CREATE INDEX IF NOT EXISTS idx_registration_entry_status ON registration(entry_id,status);
CREATE INDEX IF NOT EXISTS idx_student_campus ON student(campus_id,status);
CREATE INDEX IF NOT EXISTS idx_payments_student ON payment_record(student_id,created_at);
CREATE TABLE IF NOT EXISTS migration_control(id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO migration_control(id,enabled) VALUES(1,0);
-- Capacity invariants are enforced inside the same D1 write statement, not via an earlier page check.
CREATE TRIGGER IF NOT EXISTS class_capacity_insert BEFORE INSERT ON enrollment WHEN NEW.status='active' AND (SELECT enabled FROM migration_control WHERE id=1)=0 AND (SELECT capacity FROM class_group WHERE id=NEW.class_group_id)>0 AND (SELECT COUNT(*) FROM enrollment WHERE class_group_id=NEW.class_group_id AND status='active') >= (SELECT capacity + CASE WHEN allow_override=1 THEN override_extra ELSE 0 END FROM class_group WHERE id=NEW.class_group_id) BEGIN SELECT RAISE(ABORT,'CLASS_FULL'); END;
CREATE TRIGGER IF NOT EXISTS class_capacity_update BEFORE UPDATE OF status ON enrollment WHEN NEW.status='active' AND OLD.status!='active' AND (SELECT enabled FROM migration_control WHERE id=1)=0 AND (SELECT capacity FROM class_group WHERE id=NEW.class_group_id)>0 AND (SELECT COUNT(*) FROM enrollment WHERE class_group_id=NEW.class_group_id AND status='active') >= (SELECT capacity + CASE WHEN allow_override=1 THEN override_extra ELSE 0 END FROM class_group WHERE id=NEW.class_group_id) BEGIN SELECT RAISE(ABORT,'CLASS_FULL'); END;

CREATE TRIGGER IF NOT EXISTS registration_capacity_update BEFORE UPDATE OF class_group_id ON registration WHEN NEW.status='pending' AND NEW.class_group_id!=OLD.class_group_id AND (SELECT enabled FROM migration_control WHERE id=1)=0 AND (SELECT capacity FROM class_group WHERE id=NEW.class_group_id)>0 AND (SELECT COUNT(*) FROM enrollment WHERE class_group_id=NEW.class_group_id AND status='active')+(SELECT COUNT(*) FROM registration WHERE class_group_id=NEW.class_group_id AND status='pending') >= (SELECT capacity + CASE WHEN allow_override=1 THEN override_extra ELSE 0 END FROM class_group WHERE id=NEW.class_group_id) BEGIN SELECT RAISE(ABORT,'REGISTRATION_FULL'); END;
